"""Offline portrait/pose review and listening gallery, using real exports."""
from pathlib import Path
from PIL import Image,ImageDraw
import json,wave,math
import numpy as np
ROOT=Path(__file__).resolve().parents[2];ART=ROOT/'art/concepts/elves-v1';SOUND=ROOT/'art/concepts/sound-v1'
STYLE='''@font-face{font-family:Field;src:url('../../fonts/source-sans-3/SourceSans3-Variable.ttf')}*{box-sizing:border-box}:root{font-family:Field,system-ui,sans-serif;color:#e6dac1;background:#141c17;color-scheme:dark}body{max-width:1350px;margin:auto;padding:clamp(12px,3vw,32px)}h1,h2{font-weight:500}h1{font-size:clamp(26px,4vw,38px);margin:0 0 8px}h2{font-size:23px}p{line-height:1.5;color:#bac2b0}a{color:#dfba78}button,select,input{font:inherit;font-size:17px}button,select{min-height:44px;padding:8px 13px;border:1px solid #617055;border-radius:4px;background:#26352a;color:#e6dac1}button{cursor:pointer}button[aria-selected=true]{border-color:#d9b676;background:#424936}button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #d9b676;outline-offset:2px}.controls{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:16px 0}label{display:flex;align-items:center;gap:8px;min-height:44px}section[hidden]{display:none!important}.card{padding:16px;border:1px solid #45533e;background:#1d2820;border-radius:6px;min-width:0}.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.stage{display:flex;align-items:center;justify-content:center;padding:12px;background:#0b120d;min-height:400px}.stage[data-bg=stone]{background:#676557}.stage[data-bg=linen]{background:#d2c4a3}canvas,.pixel{image-rendering:pixelated}.stage canvas,.stage img{width:384px;height:auto;max-width:100%;object-fit:contain}.small{display:flex;align-items:center;gap:16px;margin-top:12px}.small canvas{width:96px;height:96px}.capture{max-width:100%;height:auto;border:1px solid #46533f}summary{cursor:pointer;min-height:44px;padding-top:10px;color:#dfba78}details{margin:12px 0;overflow-wrap:anywhere}pre{white-space:pre-wrap;line-height:1.4}.note{font-size:15px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,285px),1fr));gap:16px}.wave{width:100%;height:50px;object-fit:fill}.sound-card h2{font-size:21px;margin:4px 0}.sound-card p{font-size:15px;min-height:42px}.sound-card button{min-width:90px}audio{width:100%;min-height:44px}input[type=range]{height:44px;max-width:180px}input[type=checkbox]{width:22px;height:22px}.player{position:sticky;top:0;z-index:2;background:#19241d;border:1px solid #607051;padding:12px;border-radius:6px}.player h2{margin:0 0 8px;font-size:20px}@media(max-width:760px){.columns{grid-template-columns:1fr}.stage{min-height:280px}.sound-card p{min-height:0}.player{position:relative}}'''
cat=json.loads((ROOT/'art/portraits/elves-v1/catalog.json').read_text());sources=json.loads((ROOT/'art/source/elves-v1/generation.json').read_text())['assets']
portrait=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Depths · Elves</title><style>__STYLE__</style></head><body><h1>Elves</h1><p>Two individual faces and one swordswoman. Pause each drawing, inspect the clean character, and compare the game-sized portraits. Story identities and roles remain unassigned.</p><nav class="controls"><button id="portrait-tab" aria-selected="true">Portraits</button><button id="combat-tab" aria-selected="false">Combat poses</button><a href="../sound-v1/inspector.html">Sound effects →</a></nav>
<section id="portraits"><div class="controls"><label>Face <select id="face"><option value="elf-man">Elf man</option><option value="elf-woman">Elf woman</option></select></label><label>Eyes <select id="eyes"><option value="neutral">Rest</option><option value="half">Half</option><option value="closed">Closed</option></select></label><label>Mouth <select id="mouth"><option value="neutral">Rest</option><option value="small">Small</option><option value="open">Open</option><option value="round">Round</option></select></label><button id="step">Step frame</button><button id="play">Play frames</button><label><input type="checkbox" id="bare">Clean character only</label></div><div class="columns"><div class="card"><div class="controls"><label>Backdrop <select id="backdrop"><option value="dark">Dark</option><option value="stone">Stone</option><option value="linen">Linen</option></select></label><span id="held">Paused</span></div><div class="stage" id="portrait-stage" data-bg="dark"><canvas id="portrait" width="192" height="192" aria-label="Held native portrait composition"></canvas></div><div class="small"><canvas id="card" width="96" height="96" aria-label="96 pixel party card preview"></canvas><p class="note">96px card · full layers remain aligned on a 192px canvas.</p></div></div><div class="card"><h2>In the portrait renderer</h2><label>View <select id="portrait-shot"><option value="runtime-held-192">Held frames · 192px</option><option value="runtime-held-96">Held frames · 96px</option><option value="runtime-lighting">Neutral / warm / dim lighting</option></select></label><p class="note">Actual game component captures. Lighting remains separate from the character.</p><img id="portrait-capture" class="capture" src="runtime-held-192.png" alt="Real portrait renderer capture"><p><a href="features-enlarged.png">Enlarged eye and mouth drawings</a> · <a href="../../../docs/elves-and-sound-art.md">Handoff</a></p></div></div></section>
<section id="combat" hidden><div class="controls"><label>Pose <select id="pose"><option value="idle">Standing</option><option value="attack">Attack</option><option value="hurt">Hurt</option></select></label><button id="pose-step">Step pose</button><label>View <select id="combat-size"><option value="phone">Phone</option><option value="desktop">Desktop</option></select></label></div><div class="columns"><div class="card"><div class="stage"><img id="sprite" class="pixel" src="../../enemies/elves-v1/swordswoman/idle.png" alt="Elf swordswoman held combat pose"></div><p>Shared native128 canvas, 32 colours and floor pivot. The sabre and all body parts remain inside every frame.</p></div><div class="card"><h2>In combat</h2><img id="combat-capture" class="capture" src="combat-idle-phone.png" alt="Actual first-person combat capture"><p class="note">Disposable art fixture: the preview does not assign elf identities to the existing heroes or add an encounter.</p></div></div></section>
<details><summary>Original masters and exact ImageGen prompts</summary><div id="sources"></div></details><script>
const DATA=__DATA__,by=id=>document.getElementById(id),cache=new Map();let timer=null,ticket=0,stepIndex=0;
window.elfState={playing:false,tab:'portrait'};
function loadImage(src){if(!cache.has(src)){const im=new Image();im.src=src;cache.set(src,im.decode().then(()=>im))}return cache.get(src)}
function stop(){clearInterval(timer);timer=null;elfState.playing=false;by('play').textContent='Play frames'}
async function paint(){const mine=++ticket,id=by('face').value,path='../../portraits/elves-v1/'+id+'/',names=['character-clean','eyes-'+by('eyes').value,'mouth-'+by('mouth').value];const images=await Promise.all(names.map(n=>loadImage(path+n+'.png')));if(mine!==ticket)return;const c=by('portrait').getContext('2d');c.clearRect(0,0,192,192);c.imageSmoothingEnabled=false;c.drawImage(images[0],0,0);if(!by('bare').checked){c.drawImage(images[1],0,0);c.drawImage(images[2],0,0)}const small=by('card').getContext('2d');small.clearRect(0,0,96,96);small.imageSmoothingEnabled=false;small.drawImage(by('portrait'),0,0,96,96);by('held').textContent=(elfState.playing?'Playing':'Paused')+' · '+by('eyes').value+' / '+by('mouth').value}
function render(){window.portraitReady=paint();return window.portraitReady}
function step(){const states=[['neutral','neutral'],['half','neutral'],['closed','neutral'],['neutral','small'],['neutral','open'],['neutral','round']];stepIndex=(stepIndex+1)%states.length;[by('eyes').value,by('mouth').value]=states[stepIndex];render()}
for(const name of ['face','eyes','mouth','bare'])by(name).onchange=()=>{stop();render()};by('step').onclick=()=>{stop();step()};by('play').onclick=()=>{if(elfState.playing){stop();render()}else{elfState.playing=true;by('play').textContent='Pause frames';render();timer=setInterval(step,600)}};
by('backdrop').onchange=()=>by('portrait-stage').dataset.bg=by('backdrop').value;
function combat(){const src='../../enemies/elves-v1/swordswoman/'+by('pose').value+'.png',capture='combat-'+by('pose').value+'-'+by('combat-size').value+'.png';window.poseReady=Promise.all([loadImage(src),loadImage(capture)]).then(([sprite,shot])=>{if(by('pose').value!==src.split('/').pop().replace('.png','')||capture!=='combat-'+by('pose').value+'-'+by('combat-size').value+'.png')return;by('sprite').src=sprite.src;by('combat-capture').src=shot.src;return Promise.all([by('sprite').decode(),by('combat-capture').decode()])})}
by('pose').onchange=combat;by('combat-size').onchange=combat;by('pose-step').onclick=()=>{const p=['idle','attack','hurt'];by('pose').value=p[(p.indexOf(by('pose').value)+1)%3];combat()};
for(const name of ['portrait','combat'])by(name+'-tab').onclick=()=>{stop();elfState.tab=name;by('portraits').hidden=name!=='portrait';by('combat').hidden=name!=='combat';by('portrait-tab').setAttribute('aria-selected',String(name==='portrait'));by('combat-tab').setAttribute('aria-selected',String(name==='combat'));if(name==='combat')combat()};
by('portrait-shot').onchange=()=>{by('portrait-capture').src=by('portrait-shot').value+'.png'};
for(const s of DATA.sources){const detail=document.createElement('details'),sum=document.createElement('summary'),link=document.createElement('a'),pre=document.createElement('pre');sum.textContent=s.id;link.href='../../../'+s.source;link.textContent='Open original master';pre.textContent=s.prompt;detail.append(sum,link,pre);by('sources').append(detail)}
window.artReadyPromise=Promise.all([render(),by('portrait-capture').decode()]);
</script></body></html>'''
(ART/'inspector.html').write_text(portrait.replace('__STYLE__',STYLE).replace('__DATA__',json.dumps({'catalog':cat,'sources':sources})),encoding='utf-8',newline='\n')
sound=json.loads((ROOT/'audio/dark-v1/catalog.json').read_text());(SOUND/'waveforms').mkdir(exist_ok=True)
for e in sound['assets']:
 with wave.open(str(ROOT/e['path'][6:]),'rb') as w:a=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float)/32768
 chunks=np.array_split(a,200);lines=[]
 for i,chunk in enumerate(chunks):
  low=float(chunk.min()) if len(chunk) else 0;high=float(chunk.max()) if len(chunk) else 0
  lines.append(f'<path d="M{i*2} {25-high*42:.2f}v{max(.7,(high-low)*42):.2f}"/>')
 (SOUND/'waveforms'/(e['id']+'.svg')).write_text('<svg xmlns="http://www.w3.org/2000/svg" width="400" height="50" viewBox="0 0 400 50"><g stroke="#d2b176" stroke-width="1.5">'+''.join(lines)+'</g></svg>')
audio=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Depths · Dark sound library</title><style>__STYLE__</style></head><body><h1>Dark sound library</h1><p>Thirty finished effects and ambience layers, made from credited CC0 foley with original sound-design layers. Dense material contact, subdued metal and distant camp life.</p><p><a href="../elves-v1/inspector.html">← Elf artwork</a> · <a href="../../../audio/dark-v1/CREDITS.md">Source credits and licences</a> · <a href="../../../docs/elves-and-sound-art.md">Handoff</a></p><div class="player"><h2 id="now">Heavy contact 1</h2><audio id="player" controls preload="metadata" src="../../../audio/dark-v1/hit-1.wav"></audio><div class="controls"><label>Volume <input id="volume" type="range" min="0" max="1" value="0.35" step="0.01"></label><label><input id="loop" type="checkbox">Repeat ambience</label><button id="stop">Stop</button><button id="reel">Play complete reel</button></div></div><div class="controls"><label>Show <select id="filter"><option value="all">All sounds</option><option value="combat">Combat</option><option value="items">Items and interface</option><option value="camp">Camp and atmosphere</option><option value="fortress">Fortress</option></select></label><span id="count">30 sounds</span></div><div class="grid" id="sounds"></div><p class="note">Camp fire, wind and murmur are also supplied separately. The live camp uses the combined bed; the held-torch crackle stem is ready for an optional future loop. The complete reel uses four-second excerpts of ambience.</p><script>
const DATA=__DATA__,by=id=>document.getElementById(id),player=by('player');window.soundState={active:'hit-1'};player.volume=.35;
function group(e){if(e.id.includes('camp-')||e.id==='torch-burn-loop')return 'camp';if(e.id.includes('drum')||e.id.includes('queen')||e.id.includes('gate')||e.id.includes('outskirts'))return 'fortress';if(e.id.startsWith('hit-')||e.id.startsWith('miss-')||e.id.startsWith('block-')||['web-spit','venom','stumble','fall','heartbeat'].includes(e.id))return 'combat';return 'items'}
async function play(e){player.pause();player.src='../../../'+e.path.replace(/^res:\/\//,'');player.loop=e.loop&&by('loop').checked;soundState.active=e.id;by('now').textContent=e.label;window.playReady=player.play();await window.playReady}
for(const e of DATA.assets){const card=document.createElement('article');card.className='card sound-card';card.dataset.group=group(e);card.dataset.id=e.id;const h=document.createElement('h2'),p=document.createElement('p'),img=new Image(),row=document.createElement('div'),button=document.createElement('button'),link=document.createElement('a');h.textContent=e.label;p.textContent=e.notes||((e.loop?'Looping layer':'One shot')+' · '+e.seconds.toFixed(2)+' seconds');img.className='wave';img.src='waveforms/'+e.id+'.svg';img.alt='Actual waveform of '+e.label;row.className='controls';button.textContent='Play';button.onclick=()=>play(e);link.href='../../../'+e.path.replace(/^res:\/\//,'');link.textContent='WAV';row.append(button,link);card.append(h,img,p,row);by('sounds').append(card)}
by('volume').oninput=()=>player.volume=Number(by('volume').value);by('loop').onchange=()=>{const e=DATA.assets.find(e=>e.id===soundState.active);player.loop=!!e?.loop&&by('loop').checked};by('stop').onclick=()=>{player.pause();player.currentTime=0};by('reel').onclick=()=>{player.pause();player.src='audition.wav';player.loop=false;soundState.active='reel';by('now').textContent='Complete library · '+DATA.audition.seconds.toFixed(1)+' seconds';window.playReady=player.play()};by('filter').onchange=()=>{const value=by('filter').value;let count=0;document.querySelectorAll('.sound-card').forEach(e=>{e.hidden=value!=='all'&&e.dataset.group!==value;if(!e.hidden)count++});by('count').textContent=count+' sounds'};
window.artReadyPromise=Promise.all(Array.from(document.querySelectorAll('.wave')).map(i=>i.decode()));
</script></body></html>'''
(SOUND/'inspector.html').write_text(audio.replace('__STYLE__',STYLE).replace('__DATA__',json.dumps(sound)),encoding='utf-8',newline='\n')
# Compact visual overview; generated masters stay untouched.
board=Image.new('RGB',(960,580),'#202623');d=ImageDraw.Draw(board)
for x,ident in [(0,'elf-man'),(240,'elf-woman')]:
 image=Image.open(ROOT/'art/portraits/elves-v1'/ident/'resting.png').convert('RGBA').resize((240,240),Image.Resampling.NEAREST)
 board.paste(image,(x,28),image);d.text((x+12,8),ident,fill='#e6dac1')
for i,pose in enumerate(['idle','attack','hurt']):
 image=Image.open(ROOT/'art/enemies/elves-v1/swordswoman'/(pose+'.png')).convert('RGBA').resize((256,256),Image.Resampling.NEAREST)
 board.paste(image,(i*240,298),image);d.text((i*240+12,280),pose,fill='#e6dac1')
d.text((518,36),'ELVES',fill='#e6dac1');d.text((518,64),'192px portraits / fitted blink and talk',fill='#b9c3ad');d.text((518,90),'Separate lighting / unique rigs',fill='#b9c3ad');d.text((752,298),'128px combat',fill='#b9c3ad');d.text((752,322),'Shared 32 colours',fill='#b9c3ad')
board.save(ART/'overview.png')
print('ELVES_SOUND_REVIEW: fitted portrait/pose inspector and 30-effect listening gallery')
